CREATE TABLE IF NOT EXISTS app_user (id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,full_name VARCHAR(120) NOT NULL,role ENUM('ADMIN','MANAGER','STAFF') NOT NULL DEFAULT 'STAFF',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS category (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE IF NOT EXISTS supplier (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL,email VARCHAR(160),phone VARCHAR(40),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS warehouse (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL UNIQUE,address VARCHAR(255),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS location (id BIGINT PRIMARY KEY AUTO_INCREMENT,warehouse_id BIGINT NOT NULL,code VARCHAR(60) NOT NULL,UNIQUE(warehouse_id,code),FOREIGN KEY(warehouse_id) REFERENCES warehouse(id));
CREATE TABLE IF NOT EXISTS product (id BIGINT PRIMARY KEY AUTO_INCREMENT,sku VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,category_id BIGINT,supplier_id BIGINT,reorder_level DECIMAL(14,3) NOT NULL DEFAULT 0,cost DECIMAL(14,2) NOT NULL DEFAULT 0,price DECIMAL(14,2) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES category(id) ON DELETE SET NULL,FOREIGN KEY(supplier_id) REFERENCES supplier(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS stock_balance (product_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,location_id BIGINT NOT NULL,quantity DECIMAL(14,3) NOT NULL DEFAULT 0,PRIMARY KEY(product_id,warehouse_id,location_id),FOREIGN KEY(product_id) REFERENCES product(id),FOREIGN KEY(warehouse_id) REFERENCES warehouse(id),FOREIGN KEY(location_id) REFERENCES location(id));
CREATE TABLE IF NOT EXISTS stock_movement (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,location_id BIGINT NOT NULL,quantity DECIMAL(14,3) NOT NULL,movement_type VARCHAR(30) NOT NULL,reference_code VARCHAR(80) NOT NULL,reason VARCHAR(255),created_by BIGINT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,warehouse_id,location_id,movement_type,reference_code),FOREIGN KEY(product_id) REFERENCES product(id),FOREIGN KEY(warehouse_id) REFERENCES warehouse(id),FOREIGN KEY(location_id) REFERENCES location(id),FOREIGN KEY(created_by) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS purchase_order (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_number VARCHAR(50) NOT NULL UNIQUE,supplier_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,status ENUM('DRAFT','PENDING','APPROVED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED') NOT NULL DEFAULT 'DRAFT',ordered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(supplier_id) REFERENCES supplier(id),FOREIGN KEY(warehouse_id) REFERENCES warehouse(id));
CREATE TABLE IF NOT EXISTS purchase_order_item (id BIGINT PRIMARY KEY AUTO_INCREMENT,purchase_order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,ordered_qty DECIMAL(14,3) NOT NULL,received_qty DECIMAL(14,3) NOT NULL DEFAULT 0,cost DECIMAL(14,2) NOT NULL,FOREIGN KEY(purchase_order_id) REFERENCES purchase_order(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,action VARCHAR(100) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT,details TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES app_user(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS sales_order (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_number VARCHAR(50) NOT NULL UNIQUE,customer_name VARCHAR(160) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'COMPLETED',warehouse_id BIGINT NOT NULL,created_by BIGINT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(warehouse_id) REFERENCES warehouse(id),FOREIGN KEY(created_by) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS sales_order_item (id BIGINT PRIMARY KEY AUTO_INCREMENT,sales_order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,location_id BIGINT NOT NULL,quantity DECIMAL(14,3) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,FOREIGN KEY(sales_order_id) REFERENCES sales_order(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES product(id),FOREIGN KEY(location_id) REFERENCES location(id));
CREATE TABLE IF NOT EXISTS app_setting (setting_key VARCHAR(80) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL);
